import sys
def fractionToDecimal(numerator, denominator):
    if numerator % denominator == 0:
        return str(numerator // denominator)

    sign = '-' if (numerator < 0) ^ (denominator < 0) else ''
    numerator, denominator = abs(numerator), abs(denominator)

    integer_part = str(numerator // denominator)
    remainder = numerator % denominator

    seen_remainders = {}
    decimal_part = []

    while remainder != 0:
        if remainder in seen_remainders:
            start = seen_remainders[remainder]
            decimal_part.insert(start, '(')
            decimal_part.append(')')
            break

        seen_remainders[remainder] = len(decimal_part)
        remainder *= 10
        digit = remainder // denominator
        decimal_part.append(str(digit))
        remainder %= denominator

    if decimal_part:
        return sign + integer_part + '.' + ''.join(decimal_part)
    else:
        return sign + integer_part

if __name__ == "__main__":
    input = sys.stdin.read().strip().split()
    numerator = int(input[0])
    denominator = int(input[1])
    print(fractionToDecimal(numerator, denominator))
